content:
:root{
  --bg: #0b0b14;
  --elev: #121225;
  --card: #0f1020;
  --primary: #c084fc; /* purple */
  --accent: #8b5cf6;  /* indigo/purple */
  --text: #e5e7eb;
  --muted: #9aa3b2;
  --ring: rgba(139, 92, 246, .35);
  --radius: 16px;
  --shadow: 0 8px 30px rgba(2,6,23,.6);

  /* New: consistent edge padding with safe-area support */
  --page-pad: clamp(14px, 4vw, 22px);
}

*{box-sizing:border-box}
html,body{margin:0;padding:0}

body{
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, "Helvetica Neue", Arial;
  background:
    radial-gradient(1200px 1200px at 15% -10%, rgba(192,132,252,.14), transparent 60%),
    radial-gradient(1200px 1200px at 85% 0%, rgba(139,92,246,.12), transparent 60%),
    var(--bg);
  color: var(--text);
  line-height:1.6;
}

a{color:var(--primary);text-decoration:none}
a:hover{text-decoration:underline}

/* Container now uses page padding + iOS safe areas */
.container{
  max-width:1120px;
  margin:0 auto;
  padding-left: calc(var(--page-pad) + env(safe-area-inset-left));
  padding-right: calc(var(--page-pad) + env(safe-area-inset-right));
}

header{
  position:sticky; top:0;
  background:rgba(11,11,20,.7);
  backdrop-filter: blur(10px);
  border-bottom:1px solid rgba(148,163,184,.15);
  z-index:10;

  /* also apply safe-area to the header element itself */
  padding-left: env(safe-area-inset-left);
  padding-right: env(safe-area-inset-right);
}

.nav{display:flex;align-items:center;justify-content:space-between;padding:.85rem 0}
.brand{display:flex;align-items:center;gap:.75rem;font-weight:700}
.brand img{height:36px;width:36px;border-radius:10px;object-fit:cover;box-shadow:var(--shadow);border:1px solid rgba(148,163,184,.25)}
.brand span{letter-spacing:.3px}

.menu{display:flex;gap:1.1rem}
.menu a{padding:.45rem .7rem;border-radius:12px}
.menu a:hover{background:rgba(148,163,184,.12)}

.btn{display:inline-flex;align-items:center;gap:.5rem;padding:.7rem 1rem;border-radius:14px;border:1px solid rgba(148,163,184,.25);background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,0));box-shadow:var(--shadow)}
.btn:hover{border-color:rgba(139,92,246,.6);box-shadow:0 8px 35px var(--ring)}

.hero{padding:5.5rem 0 3rem}
.hero h1{font-size:clamp(1.8rem,4vw,2.6rem);line-height:1.15;margin:.25rem 0}
.hero p{max-width:60ch;color:var(--muted)}
.chiprow{display:flex;flex-wrap:wrap;gap:.5rem;margin:1.2rem 0}
.chip{border:1px solid rgba(148,163,184,.25);padding:.35rem .6rem;border-radius:999px;font-size:.9rem;color:var(--muted)}

section{padding:2.2rem 0}

.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:1.2rem}
.card{grid-column:span 12;background:var(--card);border:1px solid rgba(148,163,184,.15);border-radius:var(--radius);box-shadow:var(--shadow);padding:1.2rem}
@media (min-width: 880px){.card.span-6{grid-column:span 6}.card.span-4{grid-column:span 4}}

.muted{color:var(--muted)}

.timeline{position:relative;padding-left:1.2rem}
.timeline::before{content:"";position:absolute;left:.45rem;top:0;bottom:0;width:2px;background:linear-gradient(var(--accent), transparent)}
.timeline .item{position:relative;margin:1rem 0;padding-left:.6rem}
.timeline .item::before{content:"";position:absolute;left:-.2rem;top:.4rem;height:10px;width:10px;border-radius:999px;background:linear-gradient(135deg,var(--primary),var(--accent));box-shadow:0 0 0 4px rgba(139,92,246,.15)}

input, textarea{width:100%;padding:.85rem 1rem;border-radius:12px;border:1px solid rgba(148,163,184,.25);background:#121225;color:var(--text)}
input:focus, textarea:focus{outline:none;box-shadow:0 0 0 6px var(--ring);border-color:var(--primary)}

footer{padding:2rem 0;color:var(--muted);border-top:1px solid rgba(148,163,184,.15)}

/* -------------------- Mobile menu / hamburger -------------------- */
.hamburger{
  display:none;
  align-items:center;
  gap:.5rem;
  padding:.6rem .8rem;        /* slightly bigger target */
  margin-right:.15rem;         /* tiny offset from edge */
  border-radius:12px;
  border:1px solid rgba(148,163,184,.25);
  background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,0));
  color:var(--text);
  cursor:pointer;

  /* Recommended touch size for accessibility */
  min-width:44px; min-height:44px;
}
.hamburger:hover{border-color:rgba(139,92,246,.6);box-shadow:0 8px 35px var(--ring)}
.hamburger svg{stroke:currentColor;stroke-width:2;stroke-linecap:round}

@media (max-width: 880px){
  .menu{
    position:fixed;
    top:80px;
    right: calc(var(--page-pad) + env(safe-area-inset-right));
    left:  calc(var(--page-pad) + env(safe-area-inset-left));
    display:none;
    flex-direction:column;
    gap:.6rem;
    background:var(--card);
    border:1px solid rgba(148,163,184,.15);
    padding:.8rem;
    border-radius:14px;
    box-shadow:var(--shadow);
    z-index:20;
  }
  .menu.open{display:flex}
  .hamburger{display:inline-flex}
  .menu a{padding:.8rem;border-radius:8px;text-align:center}

  /* optional tiny nudge for the brand on phones */
  .brand{ padding-left:.1rem; }
}
